import unittest


class AgentTest_is_valid_ipv6(unittest.TestCase):

    def test_is_valid_ipv6_1(self):
        # Example from the docstring: a full eight-group IPv6 address is valid.
        self.assertTrue(IpUtil.is_valid_ipv6('2001:0db8:85a3:0000:0000:8a2e:0370:7334'))

    def test_is_valid_ipv6_2(self):
        # Example from the docstring: a misplaced "::" with extra colons is invalid.
        self.assertFalse(IpUtil.is_valid_ipv6('2001:0db8:85a3:::8a2e:0370:7334'))

    def test_is_valid_ipv6_3(self):
        # The method is documented to return a bool, and a valid address yields exactly True.
        result = IpUtil.is_valid_ipv6('2001:0db8:85a3:0000:0000:8a2e:0370:7334')
        self.assertIsInstance(result, bool)
        self.assertIs(result, True)

    def test_is_valid_ipv6_4(self):
        # An IPv4 address is not an IPv6 address, so it must be reported as invalid.
        self.assertFalse(IpUtil.is_valid_ipv6('192.168.0.123'))

    def test_is_valid_ipv6_5(self):
        # An empty string is not a valid IP address, so the result must be False.
        self.assertFalse(IpUtil.is_valid_ipv6(''))


if __name__ == '__main__':
    unittest.main()
